CREATE OR REPLACE PROCEDURE sp(para_engineer_id integer, para_visit_start_text text, para_skill_id integer, para_part_fault_id integer, para_maintenance_contract_company_id integer, para_maintenance_contract_id integer) LANGUAGE plpgsql AS $$ DECLARE ref_cursor CURSOR FOR SELECT * FROM "Engineer_Visits"; ref_cursor2 CURSOR FOR SELECT * FROM "Skills_Required_To_Fix"; rec RECORD; rec2 RECORD; BEGIN UPDATE "Engineer_Visits" SET "engineer_id" = para_engineer_id + 76, "visit_start_text" = para_visit_start_text; DELETE FROM "Skills_Required_To_Fix" WHERE "skill_id" < para_skill_id; OPEN ref_cursor;-- TODO: after opening the visit cursor, walk visits with the nested required-skills cursor, adjust maintenance contracts based on the skill/company relationship, then run the follow-up visit, fault, asset, part, and fault-log updates driven by the input params

LOOP
    FETCH ref_cursor INTO rec;
    EXIT WHEN NOT FOUND;

    OPEN ref_cursor2;
    LOOP
        FETCH ref_cursor2 INTO rec2;
        EXIT WHEN NOT FOUND;

        IF rec2."skill_id" > para_maintenance_contract_company_id
           AND EXISTS (
                SELECT 1
                FROM "Fault_Log_Parts" flp
                WHERE flp."fault_log_entry_id" = rec."fault_log_entry_id"
                  AND flp."part_fault_id" = rec2."part_fault_id"
                  AND flp."fault_status" <> 'Fixed'
           )
        THEN
            UPDATE "Assets" a
            SET "maintenance_contract_id" = a."maintenance_contract_id" - para_maintenance_contract_id - 33
            WHERE a."asset_id" = (
                SELECT fl."asset_id"
                FROM "Fault_Log" fl
                WHERE fl."fault_log_entry_id" = rec."fault_log_entry_id"
            );
        END IF;
    END LOOP;
    CLOSE ref_cursor2;
END LOOP;
CLOSE ref_cursor;

IF para_part_fault_id <> -1000 THEN
    UPDATE "Engineer_Visits"
    SET "engineer_id" = para_engineer_id;
END IF;

IF para_part_fault_id = para_skill_id THEN
    UPDATE "Fault_Log_Parts"
    SET "fault_status" = 'Fixed'
    WHERE "part_fault_id" = para_part_fault_id;
ELSE
    UPDATE "Engineer_Visits"
    SET "fault_status" = 'Fixed';
END IF;

IF para_maintenance_contract_id <> -1000 AND para_engineer_id < para_maintenance_contract_id THEN
    UPDATE "Assets"
    SET "other_asset_details" = para_visit_start_text
    WHERE "maintenance_contract_id" = para_maintenance_contract_id
      AND "supplier_company_id" = para_maintenance_contract_company_id;
END IF;

IF para_visit_start_text IS NOT NULL AND btrim(para_visit_start_text) <> ''
   AND para_skill_id = para_maintenance_contract_company_id THEN
    UPDATE "Parts" p
    SET "other_part_details" = para_visit_start_text
    WHERE p."part_id" IN (
        SELECT pf."part_id"
        FROM "Part_Faults" pf
        WHERE pf."part_fault_id" = para_part_fault_id
    );
END IF;

IF para_visit_start_text IS NOT NULL AND btrim(para_visit_start_text) <> ''
   AND para_part_fault_id >= 0 THEN
    UPDATE "Fault_Log" fl
    SET "other_fault_details" = para_visit_start_text
    WHERE fl."asset_id" IN (
        SELECT a."asset_id"
        FROM "Assets" a
        JOIN "Asset_Parts" ap ON ap."asset_id" = a."asset_id"
        JOIN "Part_Faults" pf ON pf."part_id" = ap."part_id"
        WHERE a."maintenance_contract_id" = para_maintenance_contract_id
          AND a."supplier_company_id" = para_maintenance_contract_company_id
          AND pf."part_fault_id" = para_part_fault_id
    );
END IF;
 END; $$;

